def import_existing_keys(apps: Any, schema_editor: Any) -> None:
    """Copy existing project API keys into the new credential table.

    Both hashed ("secret8.digest") and legacy plain text values are copied
    verbatim so existing keys keep working when key governance is enabled.
    """
    Project = apps.get_model("accounts", "Project")
    ApiKeyCredential = apps.get_model("accounts", "ApiKeyCredential")

    for slot in ("api_key", "api_key_readonly"):
        for project in Project.objects.exclude(**{slot: ""}).only("id", slot):
            key_hash = getattr(project, slot)
            prefix = key_hash.split(".", 1)[0] if "." in key_hash else ""
            ApiKeyCredential.objects.create(
                project_id=project.id,
                slot=slot,
                key_hash=key_hash,
                prefix=prefix,
                status="c",
            )


